  SELECT id, 'de', 'Kein eigenes B2G-Verfahren; Staatslieferanten stellen e-Factura wie jeder USt.-Pflichtige aus', 'e-Factura an RUC-Käufer; CAE genehmigt Nummernkreise vorab, keine Freigabe je Rechnung', 'Alle USt.-Pflichtigen, inkl. IVA minimo, stellen ab Jan 2025 CFE aus (e-Ticket an Verbraucher)', 'Decreto 36/012 art. 8: CFE elektronisch für die steuerliche Verjährungsfrist aufbewahren', 'Decreto 36/012 art. 7: fortgeschrittene E-Signatur mit akkreditiertem Zertifikat erforderlich'
  FROM countries WHERE name_en = 'Uruguay';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'fr', 'Pas de régime B2G distinct ; fournisseurs de l''État : e-Factura comme tout assujetti TVA', 'e-Factura aux acheteurs RUC; le CAE préautorise des plages de numéros, sans validation par facture', 'Tous assujettis TVA, dont IVA minimo : CFE (e-Ticket aux consommateurs) dès Jan 2025', 'Decreto 36/012 art. 8 : CFE conservés sous forme électronique pendant la prescription fiscale', 'Decreto 36/012 art. 7: signature électronique avancée avec certificat accrédité requise'
  FROM countries WHERE name_en = 'Uruguay';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'es', 'Sin régimen B2G aparte; proveedores del Estado: e-Factura como cualquier contribuyente de IVA', 'e-Factura a compradores con RUC; el CAE preautoriza rangos de numeración, no valida cada factura', 'Todos los sujetos de IVA, incl. IVA minimo, emiten CFE (e-Ticket a consumidores) desde Jan 2025', 'Decreto 36/012 art. 8: CFE conservados electrónicamente durante la prescripción tributaria', 'Decreto 36/012 art. 7: se exige firma electrónica avanzada con certificado acreditado'
  FROM countries WHERE name_en = 'Uruguay';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'de', 'Cabinet Resolution 522 of 25 Jun 2019: freiwillig ab 1 Jul 2019, verpflichtend für alle Unternehmen ab 1 Jan 2020.', 'Gleiche Resolution, gleiches Datum; aktuelle Rechnungsformvorgaben: Appendix 2 to Cabinet Resolution 489 of 14 Aug 2020', 'Para 18 erfasst Verkäufe an Privatpersonen; Verkäufer signiert eigene E-Rechnung. Barverkäufe mit Fiskalbeleg ausgenommen.', 'Verordnung legt 10 J. dem Plattformbetreiber auf, schweigt zum Steuerpflichtigen; unsere 5 J. nannten nicht zuordenbare Quelle.', 'Paras 14, 16 und 18 machen Signatur konstitutiv: Verkäufer signiert, Käufer signiert zur Annahme oder lehnt begründet ab.'
  FROM countries WHERE name_en = 'Uzbekistan';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'fr', 'Cabinet Resolution 522 of 25 Jun 2019: facultatif dès 1 Jul 2019, obligatoire pour toutes les entités commerciales 1 Jan 2020.', 'Même résolution, même date; règles actuelles de forme des factures: Appendix 2 to Cabinet Resolution 489 of 14 Aug 2020', 'Para 18 couvre les ventes aux particuliers; le vendeur signe sa propre e-facture. Ventes au comptant avec ticket fiscal exclues.', 'Le règlement impose 10 ans à l''opérateur de plateforme, muet sur le contribuable; nos 5 ans citaient un hôte non attribuable.', 'Paras 14, 16 et 18 rendent la signature constitutive: le vendeur signe, l''acheteur signe pour accepter ou refuse en motivant.'
  FROM countries WHERE name_en = 'Uzbekistan';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'es', 'Cabinet Resolution 522 of 25 Jun 2019: voluntario desde 1 Jul 2019, obligatorio para toda entidad empresarial 1 Jan 2020.', 'Misma resolución y misma fecha; reglas actuales de forma de factura: Appendix 2 to Cabinet Resolution 489 of 14 Aug 2020', 'Para 18 cubre ventas a particulares; el vendedor firma su propia e-factura. Ventas en efectivo con ticket fiscal excluidas.', 'Reglamento: 10 años al operador de plataforma, nada sobre el contribuyente; nuestros 5 años citaban un host no atribuible.', 'Paras 14, 16 y 18 hacen la firma constitutiva: el vendedor firma, el comprador firma para aceptar o rechaza motivadamente.'
  FROM countries WHERE name_en = 'Uzbekistan';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'de', 'Kein eigener B2G-Weg. Decree 123/2020 laut Gazette seit 1 Jul 2022 in Kraft; Gazette liefert nur ein PDF, das sie nicht freigibt.', 'Gleiches Dekret, gleiches Datum. Duales Modell: Steuerbehördencode vor Lieferung oder Übermittlung ohne Code', 'Erfasst seit Jul 2022; Decree 70/2025 weitet ab 1 Jun 2025 die Kassenvariante auf Haushalte über VND 1bn aus.', 'Zehn Jahre nach Accounting Law art.41, weiterhin sekundär: Steuerbehörde blockiert uns, Gazette hält den Text zurück.', 'Verkäufersignatur erforderlich, doch Decree 123 art.10 nennt Rechnungen ohne Signatur, u.a. Kassenbelege; womöglich bedingt.'
  FROM countries WHERE name_en = 'Vietnam';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'fr', 'Pas de volet B2G distinct. Decree 123/2020 en vigueur 1 Jul 2022 selon le Gazette, qui ne sert qu''un PDF non communiqué.', 'Même décret, même date. Double modèle: code de l''administration fiscale avant remise, ou transmission sans code', 'Dans le champ depuis Jul 2022; Decree 70/2025 étend la variante caisse dès 1 Jun 2025 aux ménages au-delà de VND 1bn.', 'Dix ans selon Accounting Law art.41, source encore secondaire: le fisc nous bloque et le Gazette retient le texte.', 'Signature du vendeur requise, mais Decree 123 art.10 liste des factures sans, dont celles de caisse; peut être conditionnel.'
  FROM countries WHERE name_en = 'Vietnam';
INSERT OR REPLACE INTO country_headline_fact_translations
  (country_id, lang, b2g_note, b2b_note, b2c_note, archiving_note, signature_note)
  SELECT id, 'es', 'Sin vía B2G separada. Decree 123/2020 en vigor 1 Jul 2022 según el Gazette, que solo sirve un PDF que no publica.', 'Mismo decreto y fecha. Modelo dual: código de la administración tributaria antes de la entrega, o envío sin él', 'En el ámbito desde Jul 2022; Decree 70/2025 amplió la variante de caja registradora desde 1 Jun 2025 a hogares sobre VND 1bn.', 'Diez años según Accounting Law art.41, aún secundaria: el departamento tributario nos bloquea y el Gazette retiene el texto.', 'Firma del vendedor requerida, pero Decree 123 art.10 lista facturas sin ella, incl. las de caja; puede ser condicional.'
  FROM countries WHERE name_en = 'Vietnam';

-- ---- what this migration claims it did ------------------------------

-- ASSERT: SELECT count(*) FROM country_headline_fact_translations WHERE lang = 'de' = 70
-- ASSERT: SELECT count(*) FROM country_headline_fact_translations WHERE lang = 'fr' = 70
-- ASSERT: SELECT count(*) FROM country_headline_fact_translations WHERE lang = 'es' = 70

-- NOTHING LANDED OVER THE CAP. Point-in-time, at the tight number, so a
-- regeneration that let one string grow fails here first.
-- ASSERT: SELECT count(*) FROM country_headline_fact_translations WHERE lang != 'en' AND (length(b2g_note) > 130 OR length(b2b_note) > 130 OR length(b2c_note) > 130 OR length(archiving_note) > 130 OR length(signature_note) > 130) = 0

-- ---- and what must stay true afterwards -----------------------------

-- FOUR LANGUAGES OR NONE. The failure this migration fixes was one
-- language having a note the other three did not. Stating it as an
-- invariant is the only thing that stops a future research migration
-- from adding an English note for a new country and quietly recreating
-- the same half-translated strip.
-- ASSERT ALWAYS: SELECT count(*) FROM (SELECT country_id FROM country_headline_fact_translations GROUP BY country_id HAVING count(DISTINCT lang) != 4) = 0

-- AND FIELD BY FIELD, NOT JUST ROW BY ROW. A de row that exists but
-- leaves b2c_note NULL where English has one is the same bug at a
-- smaller scale, and the count above cannot see it.
-- ASSERT ALWAYS: SELECT count(*) FROM country_headline_fact_translations t JOIN country_headline_fact_translations e ON e.country_id = t.country_id AND e.lang = 'en' WHERE t.lang != 'en' AND ((e.b2g_note IS NOT NULL AND t.b2g_note IS NULL) OR (e.b2b_note IS NOT NULL AND t.b2b_note IS NULL) OR (e.b2c_note IS NOT NULL AND t.b2c_note IS NULL) OR (e.archiving_note IS NOT NULL AND t.archiving_note IS NULL) OR (e.signature_note IS NOT NULL AND t.signature_note IS NULL)) = 0

-- THE PAGE STAYS ON ONE PAGE. Looser than the 130 asserted above, on
-- purpose: this is the line past which the shrink-to-fit script starts
-- costing every other row on the country's page legibility, in ANY
-- language including English.
-- ASSERT ALWAYS: SELECT count(*) FROM country_headline_fact_translations WHERE length(b2g_note) > 150 OR length(b2b_note) > 150 OR length(b2c_note) > 150 OR length(archiving_note) > 150 OR length(signature_note) > 150 = 0

